-- =====================================================================
-- ERP NOX · 013_atualizar_dados_tiny.sql
-- Completa as MATÉRIAS-PRIMAS com o relatório do Tiny "notas_fiscais_de_entrada" (09/10/2026):
--   · 8 caixas de embalagem que tinham sido classificadas como produto acabado → entram como matéria-prima
--   · unidade (só onde está vazia) em 398 itens; 38 itens em metro viram
--     estoque/uso em MM e compra em M (fator 1000) — conferir na revisão
--   · GTIN em 47 itens (só onde está vazio)
--   · 18 fornecedores criados e vinculados a 51 itens, com o código do item no fornecedor
--   · Itens cujo "fornecedor" no Tiny é a própria NOX (transferência entre as empresas) não viram
--     fornecedor; ficam anotados no produto (0 entre as matérias-primas)
--   · referência guardada no produto (não altera estoque): custo do Tiny (144 itens),
--     data da última movimentação, localização (6 itens), tipo e unidade do Tiny
--   · Quantidade em estoque NÃO é importada (será definida no inventário)
-- Como usar: Supabase → SQL Editor → New → colar tudo → Run (depois do 010, 011 e 012).
-- Pode rodar de novo sem duplicar.
-- =====================================================================
alter table public.produtos disable trigger auditoria;
alter table public.fornecedores disable trigger auditoria;
alter table public.produto_fornecedores disable trigger auditoria;

-- 1) Caixas de embalagem que faltavam
select v.codigo, v.descricao, v.grupo, 'materia_prima', v.situacao, v.observacoes, v.ref_tiny, 'tiny'
from (values
  ('4000233', 'DOWNPIPE 1020 - 410 - 260', 'Embalagem', 'inativo', 'Sem entrada/saída no Tiny desde 01/01/2025', '{"sku_tiny": "4000233", "data_ref": "2026-10-09"}'::jsonb),
  ('4000231', 'ABAFADOR PEQUENO 37 13 13', 'Embalagem', 'inativo', 'Sem entrada/saída no Tiny desde 01/01/2025', '{"sku_tiny": "4000231", "data_ref": "2026-10-09"}'::jsonb),
  ('4000229', 'ABAFADOR SIMPLES 500 170 170', 'Embalagem', 'inativo', 'Sem entrada/saída no Tiny desde 01/01/2025', '{"sku_tiny": "4000229", "data_ref": "2026-10-09"}'::jsonb),
  ('4000228', 'ABAFADOR DUPLO 620 210 170', 'Embalagem', 'inativo', 'Sem entrada/saída no Tiny desde 01/01/2025', '{"sku_tiny": "4000228", "data_ref": "2026-10-09"}'::jsonb),
  ('4000225', 'INTAKE COM FILTRO 500 330 240', 'Embalagem', 'inativo', 'Sem entrada/saída no Tiny desde 01/01/2025', '{"sku_tiny": "4000225", "data_ref": "2026-10-09"}'::jsonb),
  ('4000224', 'TUBO DAGUA 410 250 140', 'Embalagem', 'inativo', 'Sem entrada/saída no Tiny desde 01/01/2025', '{"sku_tiny": "4000224", "data_ref": "2026-10-09"}'::jsonb),
  ('4000221', 'INTAKE SEM FILTRO 400 240 200', 'Embalagem', 'inativo', 'Sem entrada/saída no Tiny desde 01/01/2025', '{"sku_tiny": "4000221", "data_ref": "2026-10-09"}'::jsonb),
  ('4000220', 'PONTEIRA SIMPLES C-160 L-140 A-140', 'Embalagem', 'inativo', 'Sem entrada/saída no Tiny desde 01/01/2025', '{"sku_tiny": "4000220", "data_ref": "2026-10-09"}'::jsonb)
) as v(codigo, descricao, grupo, situacao, observacoes, ref_tiny)
where not exists (select 1 from public.produtos p where upper(p.codigo) = upper(v.codigo));

-- 2) Dados do Tiny
drop table if exists tiny_nf; drop table if exists tiny_alvo;
create temp table tiny_nf (codigo text, descricao text, unidade text, unidade_compra text, fator numeric,
  gtin text, extra jsonb, fornecedor text, codigo_fornecedor text, grupo text);

create temp table tiny_alvo as
select p.id, t.* from tiny_nf t
join public.produtos p on p.tipo = 'materia_prima'
 and ((t.codigo is not null and upper(p.codigo) = upper(t.codigo))
   or (t.codigo is null and p.codigo is null and p.descricao_norm = public.texto_norm(t.descricao)));

update public.produtos p set
  unidade        = coalesce(p.unidade, a.unidade),
  unidade_compra = case when p.unidade is null then coalesce(p.unidade_compra, a.unidade_compra) else p.unidade_compra end,
  fator_compra   = case when p.unidade is null then coalesce(p.fator_compra, a.fator) else p.fator_compra end,
  gtin           = coalesce(p.gtin, a.gtin),
  grupo          = coalesce(a.grupo, p.grupo),
  ref_tiny       = coalesce(p.ref_tiny, '{}'::jsonb) || a.extra
from tiny_alvo a where a.id = p.id;

-- 3) Fornecedores (sem duplicar pelo nome) e vínculos
select distinct a.fornecedor from tiny_alvo a
where a.fornecedor is not null
  and not exists (select 1 from public.fornecedores f where public.texto_norm(f.nome) = public.texto_norm(a.fornecedor));

select a.id, f.id, a.codigo_fornecedor, true
from tiny_alvo a join public.fornecedores f on public.texto_norm(f.nome) = public.texto_norm(a.fornecedor)
where a.fornecedor is not null
on conflict (produto_id, fornecedor_id) do update set codigo_fornecedor = coalesce(public.produto_fornecedores.codigo_fornecedor, excluded.codigo_fornecedor);

drop table if exists tiny_nf; drop table if exists tiny_alvo;
alter table public.produtos enable trigger auditoria;
alter table public.fornecedores enable trigger auditoria;
alter table public.produto_fornecedores enable trigger auditoria;

values ('Importação', 'Importação Tiny', 'produtos', 'alterou', 'Matérias-primas: dados das NF de entrada',
        jsonb_build_object('arquivo', 'notas_fiscais_de_entrada_.xlsx', 'itens', 507, 'fornecedores', 18));
